const item = $input.first()?.json;
const message = item?.message || item?.edited_message;

if (!message || !message.text) return [];

const messageDate = message.date;
const now = Math.floor(Date.now() / 1000);

// Use 24h window (86400s) to allow testing while filtering truly ancient messages
if (Math.abs(now - messageDate) > 86400) return [];

return [{ json: item }];

const message = $input.first().json.message.text;
const match = message.match(/mangadex\.org\/chapter\/([a-f0-9-]+)/i);

if (!match) throw new Error('Could not extract chapter ID');

// --- BGM LIBRARY (all tracks) ---
const allBgmTracks = [
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype1_imagination.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype2_sakura_mitsutsuki.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype3_gurenge.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype4_kick_back.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/hype5_kaikai_kitan.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/love1_ai_no_scenario.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/love2_pride_kakumei.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad1_dakara_boku.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad2_ref_rain.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad3_yukitoki.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/sad4_kataomoi.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill1_hitchcock.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill2_vidro_moyou.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/chill3_sparkle.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic1_barricades.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic2_homura.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic3_boy.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/epic4_tot_musica.mp3",
  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/Banda%20Kaam%20Ka%20pagalall.com.mp3"
];

// Random BGM selection
const bgmUrl = allBgmTracks[Math.floor(Math.random() * allBgmTracks.length)];
const bgmName = bgmUrl.split('/').pop().replace('.mp3','').replace(/%20/g,' ');
const outroUrl = "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/outro.jpg";

return [{
  json: {
    chapterId: match[1],
    chatId: String($input.first().json.message.chat.id),
    bgmUrl: bgmUrl,
    bgmName: bgmName,
    outroUrl: outroUrl
  }
}];

const raw = $input.first().json.data || '';
const m = raw.match(/data:\s*\[([^\]]+)\]/g);
if (m && m.length) {
  const p = JSON.parse(m[m.length-1].replace('data: ',''));
  const v = p[1];
  const s = p[0] || '';
  const tm = s.match(/Done!\s*(.+?)\s*-\s*Ch\./i);
  const cm = s.match(/Ch\.?(\d+)/i);

  const mangaTitle = tm ? tm[1].trim() : 'Manga';
  const chapterNum = cm ? cm[1] : '';

  // Extract video URL - handle both string and object formats
  let videoUrl = '';
  if (typeof v === 'string') {
    videoUrl = v;
  } else if (v && v.url) {
    videoUrl = v.url;
  } else if (v && v.video && v.video.url) {
    videoUrl = v.video.url;
  }

  // Generate SEO-optimized hashtag from manga title
  const mangaHashtag = mangaTitle.replace(/[^a-zA-Z0-9]/g, '').toLowerCase();

  // Enhanced Instagram Caption with SEO
  const instagramCaption = `${mangaTitle} - Chapter ${chapterNum} ✨

🔥 New chapter just dropped! Watch the manga come to life!

📖 Manga: ${mangaTitle}
📑 Chapter: ${chapterNum}

💬 Follow for daily manga reels!

#manga #anime #mangareels #${mangaHashtag} #otaku #webtoon #mangatok #animeedit #manhwa #mangatiktok #animereels #japanmanga #mangaart #mangapanel #animefan #webtoonrecommendation #mangalover #animelovers`;

  // Enhanced YouTube Title & Description with #Shorts
  const youtubeTitle = `${mangaTitle} - Chapter ${chapterNum} | Manga Reel #Shorts #Manga #Anime`;

  const youtubeDescription = `${mangaTitle} - Chapter ${chapterNum} - Watch the manga come to life!

🔥 New manga chapter animated as a vertical reel!

📖 Manga: ${mangaTitle}
📑 Chapter: ${chapterNum}

👍 Like & Subscribe for more manga content!
🔔 Turn on notifications to never miss a upload!

━━━━━━━━━━━━━━━━━━━━━━━━━━
📌 Tags:
#Shorts #manga #anime #${mangaHashtag} #mangareels #otaku #webtoon #mangatok #animeedit #manhwa #mangatiktok #animereels #japanmanga #mangaart #animefan #webtoonrecommendation #animeshorts #mangashorts
━━━━━━━━━━━━━━━━━━━━━━━━━━

⚠️ All content belongs to the original manga creators. This video is for entertainment and promotional purposes only.`;

  return [{
    json: {
      status: s,
      mangaTitle: mangaTitle,
      chapterNum: chapterNum,
      video_url: videoUrl,
      chatId: $('Extract Chapter ID').first().json.chatId,
      bgmName: $('Extract Chapter ID').first().json.bgmName,
      instagramCaption: instagramCaption,
      youtubeTitle: youtubeTitle,
      youtubeDescription: youtubeDescription
    }
  }];
}
return [{json: {error: 'Parse failed', chatId: $('Extract Chapter ID').first().json.chatId}}];
